/* 测试验收工作台：静态嵌入，业务工件仅属于当前客户项目。 */
(function(){
'use strict';
const copy=x=>JSON.parse(JSON.stringify(x));
const freeze=x=>{if(x&&typeof x==='object'){Object.values(x).forEach(freeze);Object.freeze(x);}return x;};
const state=()=>S.test.acceptance;
S.test.acceptance={batches:[],currentBatchId:'',plans:[],runs:[],defects:[],reports:[],decisions:[],audit:[],tab:'intake'};
const batch=()=>state().batches.find(b=>b.id===state().currentBatchId);
function record(action,target){state().audit.push({action,target,at:now(),actor:'superopen'});}
function deny(message){toast(message,'warn');return false;}
window.acceptanceTab=function(tab){if(!['intake','execution','defects','delivery'].includes(tab))return false;state().tab=tab;render();return true;};
window.acceptanceReceive=function(){
 if(S.proj?.id!=='pj1')return deny('请先打开喀麦隆门户网站项目');
 const handoff=S.dev.transfer,build=S.dev.build,report=S.dev.selftest?.reports.find(r=>r.reportId===S.dev.selftest.currentReportId);
 if(!handoff||!build||!report||report.status!=='pass')return deny('尚未收到合格开发交接，请先由开发人工确认转测试');
 if(handoff.buildId!==build.buildId||!devInspectBuildUiArtifact(build).ok)return deny('交接构建与当前候选不一致，不能接收');
 const fingerprint=devHash(handoff),existing=state().batches.find(b=>b.handoffFingerprint===fingerprint);
 if(existing){state().currentBatchId=existing.id;render();return true;}
 const id='TB-'+String(state().batches.length+1).padStart(3,'0');
 const value=freeze({id,projectId:'pj1',handoff:copy(handoff),handoffFingerprint:fingerprint,build:copy(build),developmentReport:copy(report),design:copy(S.design.prototype.baselines.find(b=>b.baselineId===S.design.prototype.currentBaselineId)),environment:'本地离线原型 · 模拟环境',receivedAt:now(),receivedBy:'superopen'});
 state().batches.push(value);state().currentBatchId=id;record('batch.receive',id);toast('已接收 '+id+'，请准备并确认测试计划','success');render();return true;
};
window.acceptanceSelectBatch=function(id){if(!state().batches.some(b=>b.id===id))return false;state().currentBatchId=id;render();return true;};
window.acceptanceOpenDevelopment=function(){go('stage-dev');devSetTop('quality');};
window.acceptanceExportBatch=function(){const b=batch();if(!b)return deny('请先接收提测批次');const blob=new Blob([JSON.stringify(b,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=b.id+'-交接快照.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return true;};
const currentPlan=()=>state().plans.filter(p=>p.batchId===batch()?.id).at(-1);
window.acceptanceDraftPlan=function(){const b=batch();if(!b)return deny('请先接收批次');const cases=V19_DESIGN_CATALOG.flows.map((flow,i)=>({id:'AT-'+String(i+1).padStart(3,'0'),title:flow.title,flowId:flow.id,requirements:copy(flow.reqIds||[]),steps:copy(flow.steps),mode:'automatic',required:true}));cases.push({id:'AT-MANUAL',title:'人工走查：交互顺畅、提示清楚、关键任务可完成',requirements:[],steps:[],mode:'manual',required:true});const plan=freeze({id:'TP-'+(state().plans.length+1),batchId:b.id,cases,status:'draft',createdAt:now()});state().plans.push(plan);record('plan.draft',plan.id);render();return true;};
window.acceptanceApprovePlan=function(){const p=currentPlan();if(!p)return deny('请先起草计划');if(p.status==='approved')return true;state().plans.push(freeze({...copy(p),id:'TP-'+(state().plans.length+1),previousId:p.id,status:'approved',approvedAt:now(),approvedBy:'superopen'}));record('plan.approve',currentPlan().id);render();return true;};
window.acceptanceSetScenario=function(value){if(!['healthy','failure','blocked'].includes(value))return false;state().scenario=value;return true;};
window.acceptanceRun=function(){const b=batch(),p=currentPlan();if(!b||p?.status!=='approved')return deny('请先人工批准本批测试计划');const scenario=state().scenario||'healthy',results=p.cases.map(c=>({caseId:c.id,mode:c.mode,status:c.mode==='manual'?'not-run':scenario==='healthy'?'pass':scenario==='blocked'?'blocked':'fail',evidence:c.mode==='manual'?'等待人工记录':scenario==='healthy'?'模拟场景：正常步骤与预期匹配':scenario==='blocked'?'模拟场景：测试环境不可用':'模拟场景：实际结果不符合预期'}));const run=freeze({id:'TR-'+(state().runs.length+1),batchId:b.id,planId:p.id,environment:b.environment,scenario,status:'done',results,at:now(),simulation:true});state().runs.push(run);record('run.simulate',run.id);toast('模拟执行完成；人工项仍须验证','success');render();return true;};
function planHtml(){const p=currentPlan();if(!p)return '<section class="qa-sheet" style="margin-top:16px"><h2>准备独立测试范围</h2><p>从业务流程起草用例，并保留人工交互走查；不会复制开发通过结果。</p><button data-testid="acceptance-plan-draft" onclick="acceptanceDraftPlan()">起草测试计划</button></section>';return '<section class="qa-sheet" style="margin-top:16px"><div class="qa-sheet-head"><h2>'+esc(p.id)+' · '+(p.status==='approved'?'已批准':'待人工确认')+'</h2><button data-testid="acceptance-plan-approve" '+(p.status==='approved'?'disabled':'')+' onclick="acceptanceApprovePlan()">确认测试范围</button></div>'+p.cases.map(c=>'<p><b>'+esc(c.id)+'</b> '+esc(c.title)+' <span class="tag gray">'+(c.mode==='manual'?'人工验证':'模拟自动')+'</span></p>').join('')+'<p class="dz-note">必测项全部执行、关键项通过、无未解决缺陷，才可申请正常放行。</p></section>';}
function execution(){const p=currentPlan();if(!batch()||!p)return pending();const run=state().runs.filter(r=>r.batchId===batch().id&&r.planId===p.id).at(-1);return '<section class="qa-sheet"><div class="qa-sheet-head"><h2>按批准范围执行</h2><button data-testid="acceptance-run" '+(p.status!=='approved'?'disabled':'')+' onclick="acceptanceRun()">执行模拟用例</button></div><label>显式模拟场景 <select onchange="acceptanceSetScenario(this.value)">'+[['healthy','正常结果'],['failure','业务预期失败'],['blocked','环境阻塞']].map(([v,t])=>'<option value="'+v+'" '+((state().scenario||'healthy')===v?'selected':'')+'>'+t+'</option>').join('')+'</select></label><p class="dz-note">模拟结果不是实际软件测试证据。人工项不会自动通过，每次执行均保留新记录。</p><button data-testid="acceptance-manual" onclick="acceptanceManual()">记录人工走查结果</button><div data-testid="acceptance-results">'+p.cases.map(c=>{const r=run?.results.find(x=>x.caseId===c.id);return '<article class="qa-case"><div><b>'+esc(c.id)+' · '+esc(c.title)+'</b><p>'+esc(r?.evidence||'尚未执行')+'</p></div><span class="tag '+(r?.status==='pass'?'green':r?.status==='fail'?'red':'orange')+'">'+({pass:'模拟通过',fail:'模拟失败',blocked:'阻塞','not-run':'未执行'}[r?.status]||'未执行')+'</span></article>';}).join('')+'</div></section>';}
const currentRun=()=>state().runs.filter(r=>r.batchId===batch()?.id&&r.planId===currentPlan()?.id).at(-1);
const currentReport=()=>state().reports.filter(r=>r.batchId===batch()?.id).at(-1);
window.acceptanceManual=function(){if(!currentRun())return deny('请先执行本批用例');modal('<div class="m-head">记录人工验证</div><div class="m-body"><p>人工结论不会由自动执行代填。请记录实际操作和证据。</p><textarea id="qa-manual-evidence" rows="5" style="width:100%" placeholder="验证了哪些步骤、观察到什么结果、证据位置"></textarea><label>结论 <select id="qa-manual-result"><option value="pass">通过</option><option value="fail">失败</option><option value="blocked">阻塞</option></select></label></div><div class="m-foot"><button onclick="closeModal()">取消</button><button data-testid="acceptance-manual-save" onclick="acceptanceSaveManual()">保存人工记录</button></div>');state().manualRunId=currentRun().id;};
window.acceptanceSaveManual=function(){const run=currentRun(),evidence=document.querySelector('#qa-manual-evidence')?.value.trim(),status=document.querySelector('#qa-manual-result')?.value;if(!run||run.id!==state().manualRunId)return deny('当前运行已变化，请重新打开人工记录');if(!evidence||!['pass','fail','blocked'].includes(status))return deny('请填写验证证据与有效结论');state().runs.push(freeze({...copy(run),id:'TR-'+(state().runs.length+1),previousRunId:run.id,at:now(),results:run.results.map(r=>r.mode==='manual'?{...r,status,evidence,actor:'superopen',at:now()}:copy(r))}));record('run.manual',currentRun().id);closeModal();render();return true;};
function reportBasis(){return {batchId:batch()?.id,planId:currentPlan()?.id,runId:currentRun()?.id,defects:state().defects.map(copy)};}
window.acceptanceGenerateReport=function(){const run=currentRun(),plan=currentPlan();if(!run||plan?.status!=='approved')return deny('需要已批准计划及执行记录');const issues=run.results.filter(r=>r.status!=='pass').map(r=>r.caseId+'：'+r.status);state().defects.filter(d=>d.status!=='closed').forEach(d=>issues.push(d.id+'：未关闭缺陷'));const report=freeze({id:'AR-'+(state().reports.length+1),batchId:batch().id,basis:reportBasis(),basisFingerprint:devHash(reportBasis()),conclusion:issues.length?'fail':'pass',issues,results:copy(run.results),status:'draft',at:now(),simulation:true});state().reports.push(report);record('report.generate',report.id);render();return true;};
window.acceptanceFinalizeReport=function(){const r=currentReport();if(!r)return deny('请先生成报告');if(r.basisFingerprint!==devHash(reportBasis()))return deny('执行或缺陷已变化，请重新生成报告');if(r.status==='finalized')return true;state().reports.push(freeze({...copy(r),id:'AR-'+(state().reports.length+1),previousReportId:r.id,status:'finalized',finalizedBy:'superopen',finalizedAt:now()}));record('report.finalize',currentReport().id);render();return true;};
window.acceptanceRelease=function(){const r=currentReport();if(!r||r.status!=='finalized'||r.conclusion!=='pass'||r.basisFingerprint!==devHash(reportBasis()))return deny('放行被拒绝：需要当前全部必测通过的定稿报告');if(state().decisions.some(d=>d.reportId===r.id))return true;state().decisions.push(freeze({id:'AD-'+(state().decisions.length+1),type:'normal',batchId:batch().id,reportId:r.id,reportFingerprint:devHash(r),actor:'superopen',at:now(),simulation:true}));record('delivery.authorize',r.id);toast('已记录本批模拟交付决定，未执行生产发布','success');render();return true;};
window.acceptanceExportReport=function(){const r=currentReport();if(!r)return deny('请先生成报告');const blob=new Blob([JSON.stringify({report:r,decisions:state().decisions.filter(d=>d.reportId===r.id)},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=r.id+'-模拟验收报告.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return true;};
function delivery(){if(!batch())return pending();const r=currentReport(),fresh=r&&r.basisFingerprint===devHash(reportBasis()),released=r&&state().decisions.some(d=>d.reportId===r.id);return '<section class="qa-sheet"><div class="qa-sheet-head"><h2>报告与人工交付决定</h2><button data-testid="acceptance-report-generate" onclick="acceptanceGenerateReport()">汇总本批报告</button></div><p>报告可定稿为不通过；定稿不会把失败变绿，也不会自动放行。</p>'+(r?'<div class="banner '+(r.conclusion==='pass'?'ok':'warn')+'"><b>'+esc(r.id)+' · '+(r.conclusion==='pass'?'必测项通过':'暂不放行')+' · '+(r.status==='finalized'?'已定稿':'待审阅')+'</b>'+(!fresh?'<p>执行或缺陷已有变化，请重新汇总。</p>':'')+r.issues.map(x=>'<p>'+esc(x)+'</p>').join('')+'</div><div class="qa-actions"><button data-testid="acceptance-report-finalize" '+(r.status==='finalized'||!fresh?'disabled':'')+' onclick="acceptanceFinalizeReport()">人工定稿报告</button><button data-testid="acceptance-release" '+(r.status!=='finalized'||r.conclusion!=='pass'||!fresh||released?'disabled':'')+' onclick="acceptanceRelease()">确认本批交付</button><button onclick="acceptanceExportReport()">导出报告与决定</button></div>'+(released?'<p class="banner ok">本批交付决定已记录。模拟验收不等于真实软件验收或生产发布。</p>':''):'<div class="qa-empty">尚未生成报告。先执行批准用例并记录人工验证。</div>')+'</section>';}
window.acceptanceCreateDefect=function(caseId){const run=currentRun(),result=run?.results.find(r=>r.caseId===caseId),c=currentPlan()?.cases.find(c=>c.id===caseId);if(!run||result?.status!=='fail'||!c)return deny('只能从本批实际失败记录创建缺陷');if(state().defects.some(d=>d.runId===run.id&&d.caseId===caseId))return true;const d={id:'AB-'+(state().defects.length+1),batchId:batch().id,runId:run.id,caseId,title:c.title,evidence:result.evidence,requirements:copy(c.requirements),severity:'待定级',status:'new',events:[{type:'created',at:now(),actor:'superopen'}]};state().defects.push(d);record('defect.create',d.id);render();return true;};
window.acceptanceConfirmDefect=function(id){const d=state().defects.find(d=>d.id===id);if(!d||d.status!=='new')return false;modal('<div class="m-head">确认缺陷 '+esc(id)+'</div><div class="m-body"><p>'+esc(d.title)+'</p><label>严重度 <select id="qa-defect-severity"><option value="high">高：关键流程受阻</option><option value="medium">中：存在可行替代路径</option><option value="low">低：局部体验问题</option></select></label><textarea id="qa-defect-reason" rows="3" style="width:100%" placeholder="确认依据与影响范围"></textarea></div><div class="m-foot"><button onclick="closeModal()">取消</button><button onclick="acceptanceSaveDefect(\''+id+'\')">确认并登记返工请求</button></div>');};
window.acceptanceSaveDefect=function(id){const d=state().defects.find(d=>d.id===id),reason=document.querySelector('#qa-defect-reason')?.value.trim(),severity=document.querySelector('#qa-defect-severity')?.value;if(!d||d.status!=='new')return false;if(!reason||!['high','medium','low'].includes(severity))return deny('请填写确认依据与严重度');d.severity=severity;d.status='confirmed';d.events.push({type:'confirmed',reason,severity,actor:'superopen',at:now()});record('defect.confirm',id);closeModal();render();return true;};
window.acceptanceOpenRework=function(id){const d=state().defects.find(d=>d.id===id);if(!d||d.status!=='confirmed')return deny('请先确认缺陷');go('stage-dev');devSetTop('plan');devSetAttentionView('all');toast('请按 '+d.id+' 的需求关联选择任务，填写缺陷编号和原因后人工确认返工','warn');return true;};
function regressionEvidence(d){const b=batch(),run=currentRun(),source=state().batches.find(b=>b.id===d.batchId),originPlan=state().plans.find(p=>p.id===state().runs.find(r=>r.id===d.runId)?.planId),originCase=originPlan?.cases.find(c=>c.id===d.caseId),newCase=currentPlan()?.cases.find(c=>c.id===d.caseId);if(!b||!run||!source||b.id===source.id||b.build.buildId===source.build.buildId||devHash(b.build.commits)===devHash(source.build.commits))return null;if(!originCase||!newCase||devHash(originCase)!==devHash(newCase))return null;const result=run.results.find(r=>r.caseId===d.caseId);if(!result||result.status!=='pass')return null;return {batchId:b.id,buildId:b.build.buildId,buildFingerprint:devHash(b.build),runId:run.id,caseId:d.caseId,resultFingerprint:devHash(result)};}
window.acceptanceLinkRegression=function(id){const d=state().defects.find(d=>d.id===id);if(!d||!['confirmed','regression'].includes(d.status))return deny('请先确认缺陷及严重度');const evidence=regressionEvidence(d);if(!evidence)return deny('需要新构建批次、相同版本用例和通过的回归记录');d.regression=evidence;d.status='regression';d.events.push({type:'regression.link',evidence:copy(evidence),actor:'superopen',at:now()});record('defect.regression',id);render();return true;};
window.acceptanceCloseDefect=function(id){const d=state().defects.find(d=>d.id===id);if(!d||d.status!=='regression'||!d.regression||devHash(d.regression)!==devHash(regressionEvidence(d)))return deny('缺少当前新构建回归证据，不能关闭缺陷');d.status='closed';d.events.push({type:'closed',evidence:copy(d.regression),actor:'superopen',at:now()});record('defect.close',id);render();return true;};
window.acceptanceReopenDefect=function(id){const d=state().defects.find(d=>d.id===id);if(!d||d.status!=='closed')return false;d.status='confirmed';d.events.push({type:'reopened',actor:'superopen',at:now()});record('defect.reopen',id);render();return true;};
function defectsHtml(){if(!batch())return pending();const run=currentRun(),failed=run?.results.filter(r=>r.status==='fail')||[],defects=state().defects;return '<section class="qa-sheet" data-testid="acceptance-defects"><h2>失败必须有去向，修复必须有回归</h2><p class="dz-note">开发修复不能直接关闭缺陷；切换模拟场景也不会关闭缺陷或清除原始失败记录。</p>'+failed.filter(r=>!defects.some(d=>d.runId===run.id&&d.caseId===r.caseId)).map(r=>'<article class="qa-case"><div><b>'+esc(r.caseId)+'</b><p>'+esc(r.evidence)+'</p></div><button data-testid="acceptance-create-defect" onclick="acceptanceCreateDefect(\''+r.caseId+'\')">登记失败缺陷</button></article>').join('')+defects.map(d=>'<article class="qa-case"><div><b>'+esc(d.id)+' · '+esc(d.title)+'</b><p>'+esc(d.caseId)+' / '+esc(d.runId)+' · '+esc(d.severity)+' · '+esc(d.evidence)+'</p><span class="tag orange">'+({new:'新建',confirmed:'已确认',regression:'回归通过待确认',closed:'已关闭'}[d.status]||d.status)+'</span></div><div>'+(d.status==='new'?'<button onclick="acceptanceConfirmDefect(\''+d.id+'\')">确认与定级</button>':(d.status==='closed'?'<button onclick="acceptanceReopenDefect(\''+d.id+'\')">重新打开</button>':d.status==='regression'?'<button onclick="acceptanceCloseDefect(\''+d.id+'\')">确认关闭缺陷</button>':'<button onclick="acceptanceOpenRework(\''+d.id+'\')">前往开发返工</button><button onclick="acceptanceLinkRegression(\''+d.id+'\')">关联本批回归证据</button>'))+'</div></article>').join('')+(!failed.length&&!defects.length?'<div class="qa-empty">本批暂无登记缺陷。尚未执行不等于没有缺陷。</div>':'')+'</section>';}
function intake(){const b=batch();if(!b)return '<section class="qa-empty"><div class="qa-symbol">⇥</div><h2>等待开发交付一份可测试的候选</h2><p>尚未收到提测批次。开发完成自测后，由你确认转测试；这里再明确接收，避免测错版本。</p><div class="qa-actions"><button data-testid="acceptance-receive" '+(!S.dev.transfer?'disabled':'')+' onclick="acceptanceReceive()">接收本批提测</button><button onclick="acceptanceOpenDevelopment()">查看开发自测与交接</button></div><small>接收不代表测试通过，也不会自动批准测试计划。</small></section>';
 return '<section class="qa-sheet"><div class="qa-sheet-head"><div><span class="qa-eyebrow">交付物已固定</span><h2>'+esc(b.id)+' · '+esc(b.build.buildId)+'</h2></div><button onclick="acceptanceExportBatch()">导出交接快照</button></div><dl class="qa-facts"><div><dt>候选构建</dt><dd>'+esc(b.build.buildId)+'</dd></div><div><dt>开发自测</dt><dd>'+esc(b.developmentReport.reportId)+' · 通过</dd></div><div><dt>设计依据</dt><dd>'+esc(b.design?.baselineId||'缺少基线')+'</dd></div><div><dt>环境</dt><dd>'+esc(b.environment)+'</dd></div><div><dt>接收人</dt><dd>'+esc(b.receivedBy)+'</dd></div><div><dt>接收时间</dt><dd>'+esc(b.receivedAt)+'</dd></div></dl><div class="banner">下一步：基于本批需求和设计确认测试范围。开发自测证据仅作参考，不计为独立测试通过。</div></section>';
}
function pending(){return '<section class="qa-empty"><div class="qa-symbol">○</div><h2>'+(!batch()?'先接收提测批次':'先确认本批测试计划')+'</h2><p>'+(!batch()?'测试对象必须绑定明确构建，不能对尚未接收的候选产生执行和放行记录。':'本页尚无已批准执行记录，不展示预置的通过率或虚构的验收结果。')+'</p><button onclick="acceptanceTab(\'intake\')">返回提测与计划</button></section>';}
window.viewTest=function(){const b=batch(),tabs=[['intake','提测与计划'],['execution','用例与执行'],['defects','缺陷与回归'],['delivery','报告与交付']];return '<div class="view"><div class="subtabs">'+tabs.map(([id,label])=>'<button class="subtab '+(state().tab===id?'active':'')+'" onclick="acceptanceTab(\''+id+'\')">'+label+'</button>').join('')+'</div><div class="stage-body"><div class="doc-area qa-workbench" data-testid="acceptance-workbench"><header class="qa-header"><div><span class="qa-eyebrow">S4 / 独立测试验收</span><h1>把交付结论建立在证据上</h1><p>固定候选 → 确认范围 → 独立验证 → 人工交付</p></div><span class="tag orange">模拟执行 · 非真实实测</span></header><div class="qa-batchbar"><label>当前批次 <select aria-label="测试批次" onchange="acceptanceSelectBatch(this.value)">'+(state().batches.length?state().batches.map(x=>'<option '+(x.id===b?.id?'selected':'')+' value="'+x.id+'">'+x.id+' · '+esc(x.build.buildId)+'</option>').join(''):'<option>尚未接收</option>')+'</select></label><span>'+esc(b?.environment||'等待开发人工确认转测试')+'</span>'+(b?'<button data-testid="acceptance-receive" onclick="acceptanceReceive()">接收新交接</button>':'')+'</div><main class="qa-content">'+(state().tab==='intake'?intake()+(b?planHtml():''):state().tab==='execution'?execution():state().tab==='delivery'?delivery():state().tab==='defects'?defectsHtml():pending())+'</main><footer class="qa-footer">当前页面会话保存 · 刷新恢复示例　/　报告定稿 ≠ 放行 ≠ 生产发布</footer></div>'+chatDockHtml()+'</div></div>';};
})();
